INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('WSSQYGPJQSSYQTCR', '04', 'SQL', 'select ceil(n.mdate-date''${valDate}'') as RVALUE,m.FINPROD_ID as RKEY,n.FINPROD_NAME AS RKEYCN from PTL_SEC_VALUTION m
