where  m.PORTFOLIO_ID in ${portfolioCode} and m.CDATE = date''${valDate}''', 'assetCode', 'N', 'admin', '001', TIMESTAMP '2020-06-03 15:12:54', 'admin', TIMESTAMP '2020-06-03 15:12:54');
